(()=>{document.addEventListener("DOMContentLoaded",()=>{typeof Swiper>"u"||document.querySelectorAll(".swiper-container[data-imgloop]").forEach(e=>{e.dataset.imgloopInitialized!=="true"&&(new Swiper(e,{pagination:e.querySelector(".swiper-pagination"),paginationClickable:!0,autoHeight:!0,keyboardControl:!0,mousewheelControl:!0,lazyLoading:!0,lazyLoadingInPrevNext:!0,loop:!1}),e.dataset.imgloopInitialized="true")})},{once:!0});})();
